type ClipId = 'idle' | 'walk_down' | 'walk_up' | 'walk_left' | 'walk_right' | 'typing' | 'celebrate' | 'tired';
type Anchor = 'feet' | 'seat';
type Bounds = { x: number; y: number; width: number; height: number };
type Region = { id: string; x: number; y: number; w: number; h: number; locked: boolean };
type ResizeHandle = 'nw' | 'n' | 'ne' | 'e' | 'se' | 's' | 'sw' | 'w';
type SliceInteraction = { mode: 'create' | 'move' | 'resize'; start: { x: number; y: number }; index: number; original?: Region; handle?: ResizeHandle };
type Point = { x: number; y: number };
type DirectionFlags = { top: boolean; bottom: boolean; left: boolean; right: boolean };
type EdgeQa = { whiteFringe: number; weakAlpha: number; erodedRatio: number; sliceClipped?: DirectionFlags; canonicalOverflow?: DirectionFlags };
type Frame = { canvas: HTMLCanvasElement; raw: HTMLCanvasElement; cleaned: HTMLCanvasElement; bbox: Bounds | null; partialAlpha: number; source: string; frameOffset: Point; sliceRect: Region; edgeQa: EdgeQa };
type RawFrame = { canvas: HTMLCanvasElement; source: string };
type ClipSpec = { id: ClipId; label: string; fps: number; loop: boolean; recommended: number; anchor: Anchor };
type ClipConfig = { offset: Point; sourcePivot: Point | null; actionScale: number; suggestedActionScale: number | null };
type ReferencePreviewConfig = { source: 'action' | 'external' | 'none'; action: ClipId; frame: number; opacity: number; x: number; y: number; scale: number; displayMode: 'overlay' | 'side'; locked: boolean; externalName: string };
type CharacterConfig = { canonicalScale: number; canonicalScaleLocked: boolean; characterScaleCorrection: number; standingPivot: Point; seatPivot: Point; referenceAction: ClipId };
type Slot = { index: number; visualId: string; clips: Record<ClipId, Frame[]>; clipConfig: Record<ClipId, ClipConfig>; config: CharacterConfig };
type BackgroundSettings = { enabled: boolean; backgroundColor: string; autoCornerSample: boolean; colorTolerance: number; edgeConnectedOnly: boolean; protectInternalRegions: boolean; spillRemoval: boolean; spillStrength: number; weakAlphaThreshold: number; edgeErodePx: number; pixelEdge: boolean; binaryAlpha: boolean; binaryAlphaThreshold: number; featherRadius: number; edgeSmooth: boolean; closedRegionThreshold: number };

const SLOT_COUNT = 18;
const SAFE_MARGIN = { top: 8, bottom: 4, left: 6, right: 6 };
const noDirections = (): DirectionFlags => ({ top: false, bottom: false, left: false, right: false });
const specs: ClipSpec[] = [
  { id: 'idle', label: '待机', fps: 6, loop: true, recommended: 4, anchor: 'feet' },
  { id: 'walk_down', label: '向下行走', fps: 8, loop: true, recommended: 8, anchor: 'feet' },
  { id: 'walk_up', label: '向上行走', fps: 8, loop: true, recommended: 8, anchor: 'feet' },
  { id: 'walk_left', label: '向左行走', fps: 8, loop: true, recommended: 8, anchor: 'feet' },
  { id: 'walk_right', label: '向右行走（可选）', fps: 8, loop: true, recommended: 8, anchor: 'feet' },
  { id: 'typing', label: '打字', fps: 8, loop: true, recommended: 6, anchor: 'seat' },
  { id: 'celebrate', label: '庆祝', fps: 10, loop: false, recommended: 8, anchor: 'feet' },
  { id: 'tired', label: '疲劳', fps: 5, loop: true, recommended: 5, anchor: 'feet' },
];
const emptyClips = () => Object.fromEntries(specs.map(s => [s.id, [] as Frame[]])) as unknown as Record<ClipId, Frame[]>;
const emptyClipConfig = () => Object.fromEntries(specs.map(s => [s.id, { offset: { x: 0, y: 0 }, sourcePivot: null, actionScale: 1, suggestedActionScale: null }])) as Record<ClipId, ClipConfig>;
const defaultReferencePreview = (): ReferencePreviewConfig => ({ source: 'action', action: 'idle', frame: 0, opacity: .35, x: 0, y: 0, scale: 1, displayMode: 'overlay', locked: false, externalName: '' });
const emptyRawFrames = () => Object.fromEntries(specs.map(s => [s.id, [] as RawFrame[]])) as unknown as Record<ClipId, RawFrame[]>;
const pixelSpriteSettings = (): BackgroundSettings => ({ enabled: true, backgroundColor: '#ffffff', autoCornerSample: true, colorTolerance: 10, edgeConnectedOnly: true, protectInternalRegions: true, spillRemoval: true, spillStrength: 70, weakAlphaThreshold: 28, edgeErodePx: 1, pixelEdge: true, binaryAlpha: true, binaryAlphaThreshold: 128, featherRadius: 0, edgeSmooth: false, closedRegionThreshold: 200 });
const backgroundSettings = Object.fromEntries(specs.map(s => [s.id, pixelSpriteSettings()])) as Record<ClipId, BackgroundSettings>;
const selectedFrameIndices = Object.fromEntries(specs.map(s => [s.id, [] as number[]])) as Record<ClipId, number[]>;
const finalFrameCounts = Object.fromEntries(specs.map(s => [s.id, null as number | null])) as Record<ClipId, number | null>;
const batchScale = { canonicalScale: 0, locked: false, referenceAction: 'idle' as ClipId };
