const externalReferenceImages: (HTMLCanvasElement | null)[] = Array.from({ length: SLOT_COUNT }, () => null);
const rawFrames = emptyRawFrames();
const gridRegions = (cols = 6, rows = 3): Region[] => Array.from({ length: SLOT_COUNT }, (_, i) => ({ id: `character_${String(i + 1).padStart(2, '0')}`, x: i % cols / cols, y: Math.floor(i / cols) / rows, w: 1 / cols, h: 1 / rows, locked: false }));
const cloneRegions = (items: Region[]) => items.map(item => ({ ...item }));
const state = { slot: 0, clip: 'idle' as ClipId, frame: 0, view: 'batch' as 'batch' | 'character', playing: false, tick: 0, source: null as HTMLCanvasElement | null, sourceName: '', baseRegions: gridRegions(), actionOverrides: {} as Partial<Record<ClipId, Region[]>>, selectedSlice: 0, interaction: null as SliceInteraction | null, showBounds: true, showAnchor: true, onion: true, onionOpacity: .28, previewMode: 'transparent', edgeInspection: false, pickingBackground: false };

