$('#referenceImageInput').addEventListener('change', e => { const file = (e.target as HTMLInputElement).files?.[0], targetSlot = state.slot; if (!file) return; createImageBitmap(file).then(image => { const canvas = document.createElement('canvas'); canvas.width = image.width; canvas.height = image.height; canvas.getContext('2d')!.drawImage(image, 0, 0); externalReferenceImages[targetSlot] = canvas; const ref = referencePreviews[targetSlot]; ref.source = 'external'; ref.externalName = file.name; ref.locked = false; if (state.slot === targetSlot) { syncAlignmentControls(); renderPreview(); } }).catch(() => alert('无法读取参考图片。')); });
$('#clearReferenceImage').onclick = () => { externalReferenceImages[state.slot] = null; Object.assign(referencePreviews[state.slot], defaultReferencePreview(), { source: 'none' }); syncAlignmentControls(); renderPreview(); };
$('#alignReferencePivot').onclick = () => { const ref = referencePreviews[state.slot]; if (ref.locked) return; const canvasSize = size(), sourcePivot = ref.source === 'action' ? pivotFor(slot(), specs.find(action => action.id === ref.action)!) : slot().config.standingPivot, targetPivot = slot().config.standingPivot; ref.x = targetPivot.x - ((canvasSize.w - canvasSize.w * ref.scale) / 2 + sourcePivot.x * ref.scale); ref.y = targetPivot.y - (canvasSize.h - canvasSize.h * ref.scale + sourcePivot.y * ref.scale); syncAlignmentControls(); renderPreview(); };
$('#lockReference').onclick = () => { referencePreviews[state.slot].locked = !referencePreviews[state.slot].locked; syncAlignmentControls(); };
function updatePivot() { slot().config.standingPivot = { x: Number(($('#standX') as HTMLInputElement).value), y: Number(($('#standY') as HTMLInputElement).value) }; slot().config.seatPivot = { x: Number(($('#seatX') as HTMLInputElement).value), y: Number(($('#seatY') as HTMLInputElement).value) }; rebuildSlot(); renderAll(); }
['standX', 'standY', 'seatX', 'seatY'].forEach(id => $(`#${id}`).addEventListener('change', updatePivot));
$('#referenceAction').addEventListener('change', e => { batchScale.referenceAction = (e.target as HTMLSelectElement).value as ClipId; syncLegacyBatchScale(); slots.forEach(s => specs.forEach(action => { if (s.clips[action.id].length) estimateActionScale(s, action.id); })); renderAll(); });
function updateClipOffset() { clipConfig().offset = { x: Number(($('#clipOffsetX') as HTMLInputElement).value), y: Number(($('#clipOffsetY') as HTMLInputElement).value) }; frames().forEach(f => rebuildFrame(slot(), state.clip, f)); renderAll(); }
['clipOffsetX', 'clipOffsetY'].forEach(id => $(`#${id}`).addEventListener('change', updateClipOffset));
function updateFrameOffset() { const f = frames()[state.frame]; if (!f) return; f.frameOffset = { x: Number(($('#frameOffsetX') as HTMLInputElement).value), y: Number(($('#frameOffsetY') as HTMLInputElement).value) }; rebuildFrame(slot(), state.clip, f); renderAll(); }
['frameOffsetX', 'frameOffsetY'].forEach(id => $(`#${id}`).addEventListener('change', updateFrameOffset));
$('#onion').addEventListener('change', e => { state.onion = (e.target as HTMLInputElement).checked; renderPreview(); }); $('#onionOpacity').addEventListener('input', e => { state.onionOpacity = Number((e.target as HTMLInputElement).value); renderPreview(); });
$('#showBounds').addEventListener('change', e => { state.showBounds = (e.target as HTMLInputElement).checked; renderPreview(); }); $('#showAnchor').addEventListener('change', e => { state.showAnchor = (e.target as HTMLInputElement).checked; renderPreview(); }); $('#fps').addEventListener('change', e => { spec().fps = Math.max(1, Math.min(30, Number((e.target as HTMLInputElement).value))); renderDetails(); });
$('#play').onclick = () => { state.playing = !state.playing; $('#play').textContent = state.playing ? '❚❚ 暂停' : '▶ 播放'; }; $('#prev').onclick = () => { if (frames().length) { state.frame = (state.frame - 1 + frames().length) % frames().length; syncAlignmentControls(); renderTimeline(); renderPreview(); } }; $('#next').onclick = () => { if (frames().length) { state.frame = (state.frame + 1) % frames().length; syncAlignmentControls(); renderTimeline(); renderPreview(); } };
$('#deleteFrame').onclick = () => { if (frames().length) { frames().splice(state.frame, 1); state.frame = Math.max(0, Math.min(state.frame, frames().length - 1)); renderAll(); } }; $('#duplicateFrame').onclick = () => { const f = frames()[state.frame]; if (f) { const raw = document.createElement('canvas'); raw.width = f.raw.width; raw.height = f.raw.height; raw.getContext('2d')!.drawImage(f.raw, 0, 0); const copy = { ...f, raw, canvas: document.createElement('canvas'), frameOffset: { ...f.frameOffset }, sliceRect: { ...f.sliceRect } }; rebuildFrame(slot(), state.clip, copy); frames().splice(state.frame + 1, 0, copy); state.frame++; renderAll(); } }; $('#flipFrame').onclick = () => { const f = frames()[state.frame]; if (f) { f.raw = flip(f.raw); rebuildFrame(slot(), state.clip, f); renderAll(); } }; $('#sampleFrames').onclick = recommendedSample;
$('#mirrorRight').onclick = () => { const s = slot(); if (!s.clips.walk_left.length) return alert('当前角色没有向左行走动作'); if (s.clips.walk_right.length && !confirm('覆盖已有向右行走动作？')) return; const leftPivot = s.clipConfig.walk_left.sourcePivot; s.clipConfig.walk_right = { offset: { ...s.clipConfig.walk_left.offset }, sourcePivot: leftPivot ? { x: s.clips.walk_left[0].raw.width - leftPivot.x, y: leftPivot.y } : null, actionScale: s.clipConfig.walk_left.actionScale ?? 1, suggestedActionScale: s.clipConfig.walk_left.suggestedActionScale ?? null }; s.clips.walk_right = s.clips.walk_left.map(f => { const mirrored: Frame = { ...f, raw: flip(f.raw), canvas: document.createElement('canvas'), frameOffset: { x: -f.frameOffset.x, y: f.frameOffset.y }, sliceRect: { ...f.sliceRect } }; rebuildFrame(s, 'walk_right', mirrored); return mirrored; }); selectClip('walk_right'); };
$('#saveBatch').onclick = saveBatch; $('#exportBatch').onclick = () => exportBatch().catch(err => alert(err.message)); $('#newBatch').onclick = reset; $('#openBatch').addEventListener('change', e => { const f = (e.target as HTMLInputElement).files?.[0]; if (f) { clearRawFrames(); restoreSamplingSettings(f).then(() => openBatch(f)).then(migrateLoadedScaleSettings).catch(err => alert(err.message)); } }); $('#saveLayout').onclick = saveLayout; $('#loadLayout').addEventListener('change', e => { const f = (e.target as HTMLInputElement).files?.[0]; if (f) loadLayout(f).catch(err => alert(err.message)); }); $('#styleGuide').onclick = () => ($('#styleDialog') as HTMLDialogElement).showModal();
$('#applySlices').onclick = applySlicesToCurrentAction;
$('#resetGrid').onclick = () => { const fresh = gridRegions(); if (state.actionOverrides[state.clip]) state.actionOverrides[state.clip] = fresh; else state.baseRegions = fresh; state.selectedSlice = 0; if (($('#autoApplySlices') as HTMLInputElement).checked && rawFrames[state.clip].length) applySlicesToCurrentAction(); else renderAll(); };
$('#createOverride').onclick = () => { state.actionOverrides[state.clip] = cloneRegions(state.baseRegions); state.selectedSlice = Math.min(state.selectedSlice, SLOT_COUNT - 1); renderAll(); };
$('#clearOverride').onclick = () => { delete state.actionOverrides[state.clip]; state.selectedSlice = Math.min(state.selectedSlice, state.baseRegions.length - 1); if (($('#autoApplySlices') as HTMLInputElement).checked && rawFrames[state.clip].length) applySlicesToCurrentAction(); else renderAll(); };
$('#toggleLock').onclick = () => { const item = editableRegions()[state.selectedSlice]; if (item) { item.locked = !item.locked; renderAll(); } };
$('#deleteSlice').onclick = () => { const items = editableRegions(), item = items[state.selectedSlice]; if (!item || item.locked) return; items.splice(state.selectedSlice, 1); renumberRegions(items); state.selectedSlice = Math.max(0, Math.min(state.selectedSlice, items.length - 1)); state.slot = state.selectedSlice; renderAll(); };
$('#addSlice').onclick = () => { const items = editableRegions(); if (items.length >= SLOT_COUNT) return alert('当前已经有 18 个切片。先删除一个，再创建新切片。'); items.push({ id: `character_${String(items.length + 1).padStart(2, '0')}`, x: .35, y: .35, w: .3, h: .3, locked: false }); state.selectedSlice = items.length - 1; state.slot = state.selectedSlice; state.view = 'batch'; setViewButtons(); if (items.length === SLOT_COUNT && ($('#autoApplySlices') as HTMLInputElement).checked && rawFrames[state.clip].length) applySlicesToCurrentAction(); else renderAll(); };
document.querySelectorAll<HTMLElement>('[data-view]').forEach(el => el.onclick = () => { state.view = el.dataset.view as 'batch' | 'character'; setViewButtons(); renderPreview(); }); document.querySelectorAll<HTMLElement>('[data-bg]').forEach(el => el.onclick = () => { const bg = el.dataset.bg!; $('#stage').className = `stage ${bg === 'checker' ? '' : bg}`; });
